    .app-container { display: flex; flex: 1; overflow: hidden; }

    /* Sidebar Navigation */
    nav { width: 260px; background: #1e293b; border-right: 1px solid #334155; overflow-y: auto; display: flex; flex-direction: column; flex-shrink: 0; }
    nav .nav-header { padding: 12px 16px; font-size: 0.75rem; font-weight: 700; text-transform: uppercase; color: #64748b; letter-spacing: 0.05em; }
    nav button { background: none; border: none; color: #94a3b8; text-align: left; padding: 12px 16px; cursor: pointer; font-size: 0.875rem; display: flex; align-items: center; gap: 10px; border-left: 3px solid transparent; transition: all 0.2s; }
    nav button:hover { background: #334155; color: #f8fafc; }
    nav button.active { background: #0284c7; color: #fff; border-left-color: #38bdf8; font-weight: 600; }

    /* Content Grid */
    main { flex: 1; display: grid; grid-template-columns: 1fr 1fr; gap: 16px; padding: 16px; overflow-y: auto; }

    .panel { background: #1e293b; border: 1px solid #334155; border-radius: 8px; display: flex; flex-direction: column; overflow: hidden; }
    .panel-header { background: #0f172a; padding: 10px 16px; border-bottom: 1px solid #334155; font-weight: 600; font-size: 0.9rem; color: #38bdf8; display: flex; justify-content: space-between; align-items: center; }
    .panel-body { padding: 16px; flex: 1; overflow-y: auto; }

    /* Code Tabs Header */
    .code-tabs { display: flex; gap: 4px; background: #0f172a; padding: 6px 12px; border-bottom: 1px solid #334155; }
    .code-tab-btn { background: #1e293b; border: 1px solid #334155; color: #94a3b8; padding: 4px 12px; border-radius: 4px 4px 0 0; font-size: 0.75rem; cursor: pointer; font-weight: 600; }
    .code-tab-btn.active { background: #0284c7; color: #fff; border-color: #38bdf8; }

    /* Interactive Component Styling */
    .demo-box { background: #0f172a; border: 1px dashed #475569; border-radius: 6px; padding: 16px; min-height: 220px; margin-bottom: 16px; }
