    input, select, textarea, button.ui-btn { background: #334155; border: 1px solid #475569; color: #fff; padding: 8px 12px; border-radius: 4px; font-size: 0.875rem; outline: none; }
    input:focus, select:focus, textarea:focus { border-color: #38bdf8; }
