    function startTimer(sectionId) {
      const timerData = timers[sectionId];
      if (!timerData || timerData.interval) return;

      timerData.interval = setInterval(() => {
        if (timerData.time <= 0) {
          clearInterval(timerData.interval);
          const el = document.getElementById(timerData.timerId);
          if (el) el.textContent = "00:00";
          alert("Time's up for this section!");
          return;
        }
        timerData.time--;
        const m = Math.floor(timerData.time / 60).toString().padStart(2, '0');
        const s = (timerData.time % 60).toString().padStart(2, '0');
        const el = document.getElementById(timerData.timerId);
        if (el) el.textContent = `${m}:${s}`;
      }, 1000);
