Uniform columns = 0




Final Answer

Total uniform rows and columns = 1







Java Solution

public class UniformGridCount {



    public static int countUniformRowsAndColumns(String s) {

        int len = s.length();

        int n = (int) Math.sqrt(len);



        // Build the grid

        char[][] grid = new char[n][n];

        int index = 0;



        for (int i = 0; i < n; i++) {

            for (int j = 0; j < n; j++) {

                grid[i][j] = s.charAt(index++);

            }

        }



        int count = 0;



        // Check uniform rows

        for (int i = 0; i < n; i++) {

            boolean isUniform = true;

            for (int j = 1; j < n; j++) {

                if (grid[i][j] != grid[i][0]) {

                    isUniform = false;

                    break;

                }

            }

            if (isUniform) {

                count++;

            }

        }



        // Check uniform columns

        for (int j = 0; j < n; j++) {

            boolean isUniform = true;

            for (int i = 1; i < n; i++) {

                if (grid[i][j] != grid[0][j]) {

                    isUniform = false;

                    break;

                }

            }

            if (isUniform) {

                count++;

            }

        }



        return count;

    }



    public static void main(String[] args) {

        String s = "aaaabbbcc";

        System.out.println(countUniformRowsAndColumns(s));

    }

}




