function escapeHtml(text){return String(text).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");}
function renderQuiz(){const quizBody=document.getElementById('quiz-body');quizBody.innerHTML='';let currentSection='';quizData.forEach((q,index)=>{if(q.section!==currentSection){currentSection=q.section;const sectionHeader=document.createElement('div');sectionHeader.className='section-title';sectionHeader.innerText=currentSection;quizBody.appendChild(sectionHeader);}const card=document.createElement('div');card.className='quiz-card';card.id=`q-${index}`;let codeBlock=q.code?`<pre><code>${escapeHtml(q.code)}</code></pre>`:'';let optionsHtml=q.options.map((opt,optIndex)=>`<button class="option-btn" onclick="checkAnswer(${index},${optIndex})">${escapeHtml(String.fromCharCode(65+optIndex)+'. '+opt)}</button>`).join('');card.innerHTML=`<div class="question-number">Question ${index+1}</div><div class="question-text">${escapeHtml(q.question)}</div>${codeBlock}<div class="options-container" id="options-${index}">${optionsHtml}</div><div class="explanation" id="exp-${index}"><strong>Explanation:</strong> ${escapeHtml(q.explanation||'')}</div>`;quizBody.appendChild(card);});document.getElementById('total').innerText=quizData.length;}
function checkAnswer(qIndex,selectedOpt){if(answeredQuestions.has(qIndex))return;answeredQuestions.add(qIndex);const qData=quizData[qIndex];const buttons=document.getElementById(`options-${qIndex}`).getElementsByClassName('option-btn');for(let i=0;i<buttons.length;i++){buttons[i].disabled=true;if(i===qData.answer)buttons[i].classList.add('correct');if(i===selectedOpt&&selectedOpt!==qData.answer)buttons[i].classList.add('incorrect');}if(selectedOpt===qData.answer){currentScore++;document.getElementById('score').innerText=currentScore;}document.getElementById(`exp-${qIndex}`).style.display='block';if(answeredQuestions.size===quizData.length){const b=document.getElementById('result-banner');b.style.display='block';b.innerText=`Quiz complete — Score: ${currentScore} / ${quizData.length}`;b.scrollIntoView({behavior:'smooth',block:'center'});}}
function resetQuiz(){currentScore=0;answeredQuestions.clear();document.getElementById('score').innerText='0';document.getElementById('result-banner').style.display='none';renderQuiz();window.scrollTo({top:0,behavior:'smooth'});}
